(function initFAIPlaylabFold(global) {
  "use strict";

  // Fold is an independently designed continuous-surface instrument. The
  // simulation uses a triangular spring membrane, travelling wave fronts and
  // user-authored creases; it has no discrete falling pieces, rows or grid
  // clearing. All visuals are generated by this file at runtime.
  const FIXED_STEP_MS = 1000 / 120;
  const FIXED_STEP_SECONDS = FIXED_STEP_MS / 1000;
  const MAX_FRAME_STEPS = 12;
  const MESH_RESOLUTION = 9;
  const REQUIRED_STABILITY_MS = 1500;
  const RESONANCE_ENTRY = 0.68;
  const TRIANGLE = Object.freeze([
    Object.freeze({ x: 0.5, y: 0.075 }),
    Object.freeze({ x: 0.075, y: 0.9 }),
    Object.freeze({ x: 0.925, y: 0.9 }),
  ]);

  const TARGETS = Object.freeze({
    bridge: Object.freeze({
      signature: Object.freeze([1, 1, -1, -1, 1, 1, -1]),
      phases: Object.freeze([0, 0.15, Math.PI]),
      label: "PONTE",
    }),
    halo: Object.freeze({
      signature: Object.freeze([1, -1, 1, -1, 1, -1, 1]),
      phases: Object.freeze([0, (Math.PI * 2) / 3, (Math.PI * 4) / 3]),
      label: "CORONA",
    }),
    triad: Object.freeze({
      signature: Object.freeze([1, 1, 1, -1, -1, -1, 1]),
      phases: Object.freeze([0, Math.PI, 0.35]),
      label: "TRIADE",
    }),
  });

  const MATERIALS = Object.freeze({
    silk: Object.freeze({
      spring: 31,
      damping: 0.984,
      foldCoupling: 22,
      waveGain: 18,
      relaxation: 0.55,
      baseHue: 178,
      saturation: 78,
      lightness: 45,
    }),
    foil: Object.freeze({
      spring: 43,
      damping: 0.974,
      foldCoupling: 34,
      waveGain: 13,
      relaxation: 0.32,
      baseHue: 268,
      saturation: 72,
      lightness: 51,
    }),
    gel: Object.freeze({
      spring: 18,
      damping: 0.944,
      foldCoupling: 16,
      waveGain: 24,
      relaxation: 0.78,
      baseHue: 326,
      saturation: 83,
      lightness: 48,
    }),
  });

  const LATENCIES = Object.freeze({
    quick: Object.freeze({ delayMs: 0, intervalMs: 690, speed: 1.15, width: 13 }),
    elastic: Object.freeze({ delayMs: 95, intervalMs: 990, speed: 0.88, width: 11 }),
    echo: Object.freeze({ delayMs: 210, intervalMs: 1320, speed: 0.68, width: 9 }),
  });

  const PALETTES = Object.freeze({
    silk: Object.freeze({ background: "#041514", ink: "#d9fff8", accent: "#5ff6d4", counter: "#ffcc7a" }),
    foil: Object.freeze({ background: "#0d0818", ink: "#f1eaff", accent: "#b99cff", counter: "#70efff" }),
    gel: Object.freeze({ background: "#190713", ink: "#fff0f9", accent: "#ff73bc", counter: "#ffd86e" }),
  });

  const PROBE_POSITIONS = Object.freeze([
    Object.freeze({ x: 0.5, y: 0.23 }),
    Object.freeze({ x: 0.3, y: 0.51 }),
    Object.freeze({ x: 0.7, y: 0.51 }),
    Object.freeze({ x: 0.2, y: 0.78 }),
    Object.freeze({ x: 0.5, y: 0.78 }),
    Object.freeze({ x: 0.8, y: 0.78 }),
    Object.freeze({ x: 0.5, y: 0.56 }),
  ]);

  function clamp(value, minimum, maximum) {
    return Math.min(maximum, Math.max(minimum, value));
  }

  function round(value, places = 6) {
    const factor = 10 ** places;
    return Math.round(value * factor) / factor;
  }

  function wrapAngle(value) {
    let angle = Number(value) || 0;
    while (angle > Math.PI) angle -= Math.PI * 2;
    while (angle < -Math.PI) angle += Math.PI * 2;
    return angle;
  }

  function distance(first, second) {
    return Math.hypot(first.x - second.x, first.y - second.y);
  }

  function hashSeed(value) {
    const text = String(value);
    let hash = 2166136261;
    for (let index = 0; index < text.length; index += 1) {
      hash ^= text.charCodeAt(index);
      hash = Math.imul(hash, 16777619);
    }
    return hash >>> 0;
  }

  function makeRandom(seed) {
    let state = hashSeed(seed) || 0x6d2b79f5;
    return function random() {
      state += 0x6d2b79f5;
      let value = state;
      value = Math.imul(value ^ (value >>> 15), value | 1);
      value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
      return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
    };
  }

  function normalizeTarget(value) {
    const key = String(value ?? "bridge").trim().toLowerCase();
    if (["halo", "loop", "orbit", "ring"].includes(key)) return "halo";
    if (["triad", "triple", "triskel", "three"].includes(key)) return "triad";
    return "bridge";
  }

  function normalizeFoldBudget(value) {
    if (Number.isFinite(Number(value))) return clamp(Math.round(Number(value)), 2, 4);
    const key = String(value ?? "balanced").trim().toLowerCase();
    if (["focused", "minimal", "tight", "low"].includes(key)) return 2;
    if (["open", "generous", "wide", "high"].includes(key)) return 4;
    return 3;
  }

  function normalizeLatency(value) {
    const key = String(value ?? "elastic").trim().toLowerCase();
    if (["quick", "instant", "short", "fast", "low"].includes(key)) return "quick";
    if (["echo", "long", "slow", "high", "delayed"].includes(key)) return "echo";
    return "elastic";
  }

  function normalizePolarity(value) {
    const key = String(value ?? "alternating").trim().toLowerCase();
    if (["positive", "single", "unipolar", "one"].includes(key)) return "positive";
    if (["gesture", "responsive", "adaptive", "directional"].includes(key)) return "gesture";
    return "alternating";
  }

  function normalizeMaterial(value) {
    const key = String(value ?? "silk").trim().toLowerCase();
    if (["foil", "glass", "metal", "crystal"].includes(key)) return "foil";
    if (["gel", "fluid", "soft", "viscous"].includes(key)) return "gel";
    return "silk";
  }

  function normalizeConfig(source) {
    const input = source && typeof source === "object" ? source : {};
    return {
      seed: String(input.seed ?? "fold-default-seed"),
      targetTopology: normalizeTarget(input.targetTopology ?? input.target_topology),
      foldBudget: normalizeFoldBudget(input.foldBudget ?? input.fold_budget),
      waveLatency: normalizeLatency(input.waveLatency ?? input.wave_latency),
      polarityMode: normalizePolarity(input.polarityMode ?? input.polarity_mode),
      membraneMaterial: normalizeMaterial(input.membraneMaterial ?? input.membrane_material),
      externalHud: input.externalHud === true,
      reduceMotion: input.reduceMotion === true
        || Boolean(global.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches),
      headless: input.headless === true,
      debug: input.debug === true,
    };
  }

  function pointOnEdge(edge, position) {
    const t = clamp(Number(position) || 0, 0, 1);
    const [top, left, right] = TRIANGLE;
    if (edge === "right") {
      return { x: top.x + (right.x - top.x) * t, y: top.y + (right.y - top.y) * t, edge: "right" };
    }
    if (edge === "base" || edge === "bottom") {
      return { x: left.x + (right.x - left.x) * t, y: left.y, edge: "base" };
    }
    return { x: top.x + (left.x - top.x) * t, y: top.y + (left.y - top.y) * t, edge: "left" };
  }

  function closestPointOnSegment(point, first, second) {
    const dx = second.x - first.x;
    const dy = second.y - first.y;
    const lengthSquared = dx * dx + dy * dy || 1;
    const t = clamp(((point.x - first.x) * dx + (point.y - first.y) * dy) / lengthSquared, 0, 1);
    return { x: first.x + dx * t, y: first.y + dy * t, t };
  }

  function nearestBoundary(point) {
    const candidates = [
      { edge: "left", ...closestPointOnSegment(point, TRIANGLE[0], TRIANGLE[1]) },
      { edge: "right", ...closestPointOnSegment(point, TRIANGLE[0], TRIANGLE[2]) },
      { edge: "base", ...closestPointOnSegment(point, TRIANGLE[1], TRIANGLE[2]) },
    ];
    candidates.forEach((candidate) => {
      candidate.distance = Math.hypot(candidate.x - point.x, candidate.y - point.y);
    });
    candidates.sort((first, second) => first.distance - second.distance);
    return candidates[0];
  }

  function clampToTriangle(point) {
    const y = clamp(Number(point.y) || 0, TRIANGLE[0].y, TRIANGLE[1].y);
    const t = (y - TRIANGLE[0].y) / (TRIANGLE[1].y - TRIANGLE[0].y);
    const halfWidth = (TRIANGLE[2].x - TRIANGLE[0].x) * t;
    return { x: clamp(Number(point.x) || 0, 0.5 - halfWidth, 0.5 + halfWidth), y };
  }

  function lineDistance(point, first, second) {
    const dx = second.x - first.x;
    const dy = second.y - first.y;
    const length = Math.hypot(dx, dy) || 1;
    return ((point.x - first.x) * dy - (point.y - first.y) * dx) / length;
  }

  function createMesh() {
    const nodes = [];
    const rows = [];
    for (let row = 0; row < MESH_RESOLUTION; row += 1) {
      const rowNodes = [];
      const y = TRIANGLE[0].y + ((TRIANGLE[1].y - TRIANGLE[0].y) * row) / (MESH_RESOLUTION - 1);
      for (let column = 0; column <= row; column += 1) {
        const x = row === 0
          ? 0.5
          : 0.5 + ((column - row / 2) * (TRIANGLE[2].x - TRIANGLE[1].x)) / (MESH_RESOLUTION - 1);
        const node = { index: nodes.length, row, column, x, y, z: 0, velocity: 0, drive: 0 };
        nodes.push(node);
        rowNodes.push(node.index);
      }
      rows.push(rowNodes);
    }

    const edgeSet = new Set();
    const edges = [];
    function addEdge(first, second) {
      const low = Math.min(first, second);
      const high = Math.max(first, second);
      const key = `${low}:${high}`;
      if (edgeSet.has(key)) return;
      edgeSet.add(key);
      edges.push([low, high]);
    }
    for (let row = 0; row < MESH_RESOLUTION; row += 1) {
      for (let column = 0; column <= row; column += 1) {
        const current = rows[row][column];
        if (column < row) addEdge(current, rows[row][column + 1]);
        if (row < MESH_RESOLUTION - 1) {
          addEdge(current, rows[row + 1][column]);
          addEdge(current, rows[row + 1][column + 1]);
        }
      }
    }

    const neighbors = Array.from({ length: nodes.length }, () => []);
    edges.forEach(([first, second]) => {
      neighbors[first].push(second);
      neighbors[second].push(first);
    });

    const faces = [];
    for (let row = 0; row < MESH_RESOLUTION - 1; row += 1) {
      for (let column = 0; column <= row; column += 1) {
        faces.push([rows[row][column], rows[row + 1][column], rows[row + 1][column + 1]]);
        if (column < row) {
          faces.push([rows[row][column], rows[row][column + 1], rows[row + 1][column + 1]]);
        }
      }
    }

    const probes = PROBE_POSITIONS.map((position) => {
      let nearest = nodes[0];
      let nearestDistance = Infinity;
      nodes.forEach((node) => {
        const candidate = Math.hypot(node.x - position.x, node.y - position.y);
        if (candidate < nearestDistance) {
          nearestDistance = candidate;
          nearest = node;
        }
      });
      return nearest.index;
    });
    return { nodes, rows, edges, neighbors, faces, probes };
  }

  function stableChecksum(value) {
    return hashSeed(JSON.stringify(value)).toString(16).padStart(8, "0");
  }

  function createFold(options) {
    const settings = options && typeof options === "object" ? options : {};
    const canvas = settings.canvas;
    if (!canvas || typeof canvas.getContext !== "function") {
      throw new TypeError("FAIPlaylab.createFold requires a canvas element");
    }
    const context = canvas.getContext("2d", { alpha: false, desynchronized: true });
    if (!context) throw new Error("Canvas 2D is not available");

    const config = normalizeConfig(settings.config);
    const material = MATERIALS[config.membraneMaterial];
    const latency = LATENCIES[config.waveLatency];
    const target = TARGETS[config.targetTopology];
    const palette = PALETTES[config.membraneMaterial];
    const onEvent = typeof settings.onEvent === "function" ? settings.onEvent : () => {};
    const requestFrame = typeof global.requestAnimationFrame === "function"
      ? global.requestAnimationFrame.bind(global)
      : (callback) => global.setTimeout(() => callback(global.performance?.now?.() ?? Date.now()), 16);
    const cancelFrame = typeof global.cancelAnimationFrame === "function"
      ? global.cancelAnimationFrame.bind(global)
      : global.clearTimeout.bind(global);

    let mesh = createMesh();
    let random = makeRandom(config.seed);
    let status = "idle";
    let folds = [];
    let waves = [];
    let pointers = new Map();
    let preview = null;
    let multiGesture = null;
    let selectedFoldId = null;
    let nextFoldId = 1;
    let nextWaveId = 1;
    let nextAutoWaveAt = latency.intervalMs;
    let autoSourceIndex = 0;
    let polarityIndex = 0;
    let elapsedMs = 0;
    let stableMs = 0;
    let score = 0;
    let coherence = 0.5;
    let membraneEnergy = 0;
    let currentSignature = Array(target.signature.length).fill(0);
    let gestureCount = 0;
    let waveCount = 0;
    let topologyChecks = 0;
    let lastProgressBucket = -1;
    let rafId = 0;
    let lastFrameTime = 0;
    let accumulator = 0;
    let cssWidth = 1;
    let cssHeight = 1;
    let dpr = 1;
    let view = { x: 0, y: 0, width: 1, height: 1 };

    function emit(type, payload) {
      try {
        onEvent(type, payload ?? stateSummary());
      } catch (_error) {
        // Consumer callbacks cannot take ownership of the simulation loop.
      }
    }

    function stateSummary(extra) {
      return {
        status,
        score: Math.round(score),
        elapsedMs: round(elapsedMs, 3),
        coherence: round(coherence),
        stability: round(stableMs / REQUIRED_STABILITY_MS),
        targetTopology: config.targetTopology,
        foldCount: folds.length,
        foldBudget: config.foldBudget,
        waveCount,
        gestureCount,
        ...(extra || {}),
      };
    }

    function serializedFold(fold) {
      return {
        id: fold.id,
        edge: fold.edge,
        start: { x: round(fold.start.x), y: round(fold.start.y) },
        end: { x: round(fold.end.x), y: round(fold.end.y) },
        angle: round(fold.angle),
        strength: round(fold.strength),
        polarity: fold.polarity,
      };
    }

    function statePayload() {
      return {
        ...stateSummary(),
        seed: config.seed,
        requiredStabilityMs: REQUIRED_STABILITY_MS,
        targetSignature: target.signature.slice(),
        currentSignature: currentSignature.slice(),
        foldsRemaining: Math.max(0, config.foldBudget - folds.length),
        selectedFoldId,
        folds: folds.map(serializedFold),
        waves: waves.map((wave) => ({
          id: wave.id,
          x: round(wave.x),
          y: round(wave.y),
          ageMs: round(wave.age * 1000, 3),
          polarity: wave.polarity,
          amplitude: round(wave.amplitude),
          source: wave.source,
        })),
        membrane: {
          resolution: MESH_RESOLUTION,
          energy: round(membraneEnergy),
          nodes: mesh.nodes.map((node) => ({ x: round(node.x), y: round(node.y), z: round(node.z) })),
        },
        topologyChecks,
        config: { ...config },
      };
    }

    function getState() {
      return statePayload();
    }

    function snapshot() {
      const state = statePayload();
      return {
        ...state,
        snapshotVersion: 1,
        checksum: stableChecksum(state),
      };
    }

    function resetSimulation() {
      mesh = createMesh();
      random = makeRandom(config.seed);
      folds = [];
      waves = [];
      pointers = new Map();
      preview = null;
      multiGesture = null;
      selectedFoldId = null;
      nextFoldId = 1;
      nextWaveId = 1;
      nextAutoWaveAt = latency.intervalMs;
      autoSourceIndex = 0;
      polarityIndex = 0;
      elapsedMs = 0;
      stableMs = 0;
      score = 0;
      coherence = 0.5;
      membraneEnergy = 0;
      currentSignature = Array(target.signature.length).fill(0);
      gestureCount = 0;
      waveCount = 0;
      topologyChecks = 0;
      lastProgressBucket = -1;
      lastFrameTime = 0;
      accumulator = 0;
    }

    function resolvePolarity(direction = 1, explicit) {
      if (Number(explicit) < 0) return -1;
      if (Number(explicit) > 0) return 1;
      if (config.polarityMode === "positive") return 1;
      if (config.polarityMode === "gesture") return Number(direction) < 0 ? -1 : 1;
      const result = polarityIndex % 2 === 0 ? 1 : -1;
      polarityIndex += 1;
      return result;
    }

    function addWave(origin, source = "gesture", explicitPolarity, amplitude = 1, direction = 1) {
      if (["completed", "destroyed"].includes(status)) return false;
      const point = clampToTriangle(origin || { x: 0.5, y: 0.56 });
      const wave = {
        id: `wave-${nextWaveId}`,
        x: point.x,
        y: point.y,
        age: -(latency.delayMs / 1000),
        polarity: resolvePolarity(direction, explicitPolarity),
        amplitude: clamp(Number(amplitude) || 1, 0.25, 1.5),
        phase: (random() - 0.5) * 0.08,
        source,
      };
      nextWaveId += 1;
      waveCount += 1;
      waves.push(wave);
      if (waves.length > 22) waves.splice(0, waves.length - 22);
      emit("wave", { ...stateSummary(), wave: { ...wave, ageMs: round(wave.age * 1000, 3) } });
      return true;
    }

    function buildFold(from, to, options = {}) {
      const boundary = options.edge
        ? pointOnEdge(options.edge, options.position ?? 0.5)
        : nearestBoundary(clampToTriangle(from));
      let end = clampToTriangle(to);
      const baseAngle = Number.isFinite(Number(options.angle))
        ? wrapAngle(Number(options.angle))
        : Math.atan2(end.y - boundary.y, end.x - boundary.x);
      if (Number.isFinite(Number(options.angle))) {
        const length = clamp(Number(options.length) || 0.5, 0.12, 0.95);
        end = clampToTriangle({
          x: boundary.x + Math.cos(baseAngle) * length,
          y: boundary.y + Math.sin(baseAngle) * length,
        });
      }
      const gestureDirection = end.x - boundary.x || -(end.y - boundary.y);
      return {
        id: `fold-${nextFoldId}`,
        edge: boundary.edge || options.edge || "left",
        start: { x: boundary.x, y: boundary.y },
        end,
        angle: Math.atan2(end.y - boundary.y, end.x - boundary.x),
        strength: clamp(Number(options.strength) || 0.68, 0.16, 1),
        polarity: resolvePolarity(gestureDirection, options.polarity),
      };
    }

    function commitFold(fold, source = "swipe") {
      if (!fold || ["completed", "destroyed"].includes(status)) return false;
      if (distance(fold.start, fold.end) < 0.055) return false;
      nextFoldId += 1;
      if (folds.length >= config.foldBudget) {
        const removed = folds.shift();
        emit("fold-released", { ...stateSummary(), foldId: removed.id });
      }
      folds.push(fold);
      selectedFoldId = fold.id;
      gestureCount += 1;
      addWave(fold.end, source, fold.polarity, 1, fold.end.x - fold.start.x);
      emit("fold", { ...stateSummary(), fold: serializedFold(fold), source });
      return true;
    }

    function directFold(payload) {
      const edge = ["left", "right", "base", "bottom"].includes(String(payload.edge).toLowerCase())
        ? String(payload.edge).toLowerCase()
        : "left";
      const start = pointOnEdge(edge, payload.position ?? 0.5);
      const angle = Number.isFinite(Number(payload.angle))
        ? Number(payload.angle)
        : edge === "base" || edge === "bottom" ? -Math.PI / 2 : edge === "left" ? 0.18 : Math.PI - 0.18;
      const fold = buildFold(start, start, {
        edge,
        position: payload.position ?? 0.5,
        angle,
        length: payload.length ?? 0.52,
        strength: payload.strength,
        polarity: payload.polarity,
      });
      return commitFold(fold, payload.source || "one-finger");
    }

    function selectedFold() {
      return folds.find((fold) => fold.id === selectedFoldId) || folds[folds.length - 1] || null;
    }

    function rotateFoldEnd(fold, angle) {
      const length = clamp(distance(fold.start, fold.end), 0.12, 0.95);
      fold.angle = wrapAngle(angle);
      fold.end = clampToTriangle({
        x: fold.start.x + Math.cos(fold.angle) * length,
        y: fold.start.y + Math.sin(fold.angle) * length,
      });
      fold.angle = Math.atan2(fold.end.y - fold.start.y, fold.end.x - fold.start.x);
    }

    function adjustFold(scale, rotation, source = "adjust") {
      const fold = selectedFold();
      if (!fold || ["completed", "destroyed"].includes(status)) return false;
      const strengthScale = Number.isFinite(Number(scale)) ? Number(scale) : 1;
      const angleDelta = Number.isFinite(Number(rotation)) ? Number(rotation) : 0;
      fold.strength = clamp(fold.strength * strengthScale, 0.16, 1);
      rotateFoldEnd(fold, fold.angle + angleDelta);
      gestureCount += 1;
      addWave(fold.end, source, fold.polarity, 0.72, angleDelta || 1);
      emit("fold-adjust", { ...stateSummary(), fold: serializedFold(fold), source });
      return true;
    }

    function removeSelectedFold() {
      const fold = selectedFold();
      if (!fold) return false;
      const index = folds.indexOf(fold);
      folds.splice(index, 1);
      selectedFoldId = folds[folds.length - 1]?.id || null;
      gestureCount += 1;
      emit("fold-released", { ...stateSummary(), foldId: fold.id, source: "undo" });
      return true;
    }

    function normalizeInputPoint(payload) {
      const rect = typeof canvas.getBoundingClientRect === "function"
        ? canvas.getBoundingClientRect()
        : { left: 0, top: 0, width: cssWidth, height: cssHeight };
      let localX;
      let localY;
      if (Number.isFinite(Number(payload.clientX)) && Number.isFinite(Number(payload.clientY))) {
        localX = Number(payload.clientX) - (rect.left || 0);
        localY = Number(payload.clientY) - (rect.top || 0);
      } else if (payload.normalized === true
        || (Number(payload.x) >= 0 && Number(payload.x) <= 1 && Number(payload.y) >= 0 && Number(payload.y) <= 1)) {
        return clampToTriangle({ x: Number(payload.x), y: Number(payload.y) });
      } else {
        localX = Number(payload.x) || 0;
        localY = Number(payload.y) || 0;
      }
      return clampToTriangle({
        x: (localX - view.x) / Math.max(1, view.width),
        y: (localY - view.y) / Math.max(1, view.height),
      });
    }

    function beginPointer(payload) {
      const id = payload.pointerId ?? payload.id ?? 0;
      const point = normalizeInputPoint(payload);
      pointers.set(id, { start: point, current: point });
      if (pointers.size === 1) {
        const boundary = nearestBoundary(point);
        preview = buildFold(boundary, point, { strength: payload.strength, polarity: payload.polarity });
      } else if (pointers.size === 2) {
        // A second contact means "transform", not "author another crease".
        // Only bootstrap the very first crease when there is nothing to edit.
        if (!folds.length && preview && distance(preview.start, preview.end) >= 0.055) {
          commitFold(preview, "edge-swipe");
        }
        preview = null;
        const points = [...pointers.values()].map((pointer) => pointer.current);
        const fold = selectedFold();
        multiGesture = fold ? {
          foldId: fold.id,
          distance: Math.max(0.001, distance(points[0], points[1])),
          angle: Math.atan2(points[1].y - points[0].y, points[1].x - points[0].x),
          strength: fold.strength,
          foldAngle: fold.angle,
        } : null;
      }
      return true;
    }

    function movePointer(payload) {
      const id = payload.pointerId ?? payload.id ?? 0;
      const pointer = pointers.get(id);
      if (!pointer) return false;
      pointer.current = normalizeInputPoint(payload);
      if (pointers.size === 1 && preview) {
        preview.end = pointer.current;
        preview.angle = Math.atan2(preview.end.y - preview.start.y, preview.end.x - preview.start.x);
        preview.strength = clamp(0.34 + distance(preview.start, preview.end) * 0.9, 0.16, 1);
      } else if (pointers.size >= 2 && multiGesture) {
        const points = [...pointers.values()].slice(0, 2).map((item) => item.current);
        const currentDistance = Math.max(0.001, distance(points[0], points[1]));
        const currentAngle = Math.atan2(points[1].y - points[0].y, points[1].x - points[0].x);
        const fold = folds.find((item) => item.id === multiGesture.foldId);
        if (fold) {
          fold.strength = clamp(multiGesture.strength * (currentDistance / multiGesture.distance), 0.16, 1);
          rotateFoldEnd(fold, multiGesture.foldAngle + wrapAngle(currentAngle - multiGesture.angle));
        }
      }
      return true;
    }

    function endPointer(payload) {
      const id = payload.pointerId ?? payload.id ?? 0;
      if (!pointers.has(id)) return false;
      if (payload && (Number.isFinite(Number(payload.x)) || Number.isFinite(Number(payload.clientX)))) {
        movePointer(payload);
      }
      const wasMulti = pointers.size >= 2;
      pointers.delete(id);
      if (!wasMulti && preview) {
        commitFold(preview, "edge-swipe");
        preview = null;
      } else if (wasMulti && pointers.size < 2) {
        const fold = selectedFold();
        if (fold) {
          gestureCount += 1;
          addWave(fold.end, "pinch-rotate", fold.polarity, 0.82, 1);
          emit("fold-adjust", { ...stateSummary(), fold: serializedFold(fold), source: "pinch-rotate" });
        }
        multiGesture = null;
      }
      return true;
    }

    function cancelPointers() {
      pointers.clear();
      preview = null;
      multiGesture = null;
      return true;
    }

    function input(command) {
      if (["destroyed", "paused", "completed"].includes(status)) return false;
      const payload = typeof command === "string" ? { type: command } : command;
      if (!payload || typeof payload !== "object") return false;
      const type = String(payload.type || payload.action || "").trim().toLowerCase();
      if (["pointerdown", "touchstart", "gesturestart"].includes(type)) return beginPointer(payload);
      if (["pointermove", "touchmove", "gesturemove"].includes(type)) return movePointer(payload);
      if (["pointerup", "touchend", "gestureend"].includes(type)) return endPointer(payload);
      if (["pointercancel", "touchcancel", "cancel"].includes(type)) return cancelPointers();
      if (["fold", "swipe", "crease"].includes(type)) {
        if (payload.from && payload.to) {
          const fold = buildFold(payload.from, payload.to, payload);
          return commitFold(fold, payload.source || "swipe");
        }
        return directFold(payload);
      }
      if (["pinch", "rotate", "adjust"].includes(type)) {
        return adjustFold(payload.scale ?? 1, payload.rotation ?? payload.value ?? 0, type);
      }
      if (["pulse", "wave", "action", "space", "enter"].includes(type)) {
        const point = payload.point || (Number.isFinite(Number(payload.x)) ? normalizeInputPoint(payload) : { x: 0.5, y: 0.56 });
        gestureCount += 1;
        return addWave(point, "manual", payload.polarity, payload.amplitude, payload.direction);
      }
      if (["undo", "backspace", "delete"].includes(type)) return removeSelectedFold();
      if (type === "clear") {
        if (!folds.length) return false;
        folds = [];
        selectedFoldId = null;
        gestureCount += 1;
        emit("folds-cleared", stateSummary());
        return true;
      }
      if (type === "left") return adjustFold(1, -0.11, "one-finger-rotate");
      if (type === "right") return adjustFold(1, 0.11, "one-finger-rotate");
      if (type === "up") return adjustFold(1.12, 0, "one-finger-strength");
      if (type === "down") return adjustFold(0.88, 0, "one-finger-strength");
      return false;
    }

    function pointerPayload(type, event) {
      return {
        type,
        pointerId: event.pointerId,
        clientX: event.clientX,
        clientY: event.clientY,
        pressure: event.pressure,
      };
    }

    function onCanvasPointerDown(event) {
      if (status === "destroyed") return;
      event.preventDefault();
      canvas.setPointerCapture?.(event.pointerId);
      input(pointerPayload("pointerdown", event));
    }

    function onCanvasPointerMove(event) {
      if (!pointers.has(event.pointerId)) return;
      event.preventDefault();
      input(pointerPayload("pointermove", event));
    }

    function onCanvasPointerUp(event) {
      if (!pointers.has(event.pointerId)) return;
      event.preventDefault();
      input(pointerPayload("pointerup", event));
      if (canvas.hasPointerCapture?.(event.pointerId)) canvas.releasePointerCapture(event.pointerId);
    }

    function onCanvasPointerCancel(event) {
      if (!pointers.has(event.pointerId)) return;
      input(pointerPayload("pointercancel", event));
      if (canvas.hasPointerCapture?.(event.pointerId)) canvas.releasePointerCapture(event.pointerId);
    }

    const hasPointerEvents = typeof canvas.addEventListener === "function";
    if (hasPointerEvents) {
      canvas.addEventListener("pointerdown", onCanvasPointerDown, { passive: false });
      canvas.addEventListener("pointermove", onCanvasPointerMove, { passive: false });
      canvas.addEventListener("pointerup", onCanvasPointerUp, { passive: false });
      canvas.addEventListener("pointercancel", onCanvasPointerCancel, { passive: false });
    }

    function waveForceAt(node) {
      let force = 0;
      for (const wave of waves) {
        if (wave.age < 0) continue;
        const radialDistance = Math.hypot(node.x - wave.x, node.y - wave.y);
        const front = wave.age * latency.speed;
        const delta = radialDistance - front;
        const envelope = Math.exp(-Math.abs(delta) * latency.width) * Math.exp(-wave.age * 0.58);
        let phaseShift = 0;
        for (const fold of folds) {
          const sourceSide = lineDistance(wave, fold.start, fold.end);
          const nodeSide = lineDistance(node, fold.start, fold.end);
          if (sourceSide * nodeSide < 0) phaseShift += fold.strength * fold.polarity * 1.08;
        }
        force += Math.cos(delta * 35 + wave.phase + phaseShift) * envelope * wave.amplitude * wave.polarity;
      }
      return force;
    }

    function foldTargetAt(node) {
      let targetValue = 0;
      for (const fold of folds) {
        const signedDistance = lineDistance(node, fold.start, fold.end);
        const alongX = fold.end.x - fold.start.x;
        const alongY = fold.end.y - fold.start.y;
        const lengthSquared = alongX * alongX + alongY * alongY || 1;
        const along = ((node.x - fold.start.x) * alongX + (node.y - fold.start.y) * alongY) / lengthSquared;
        const reach = Math.exp(-Math.max(0, -along) * 8 - Math.max(0, along - 1) * 8);
        const ridge = Math.exp(-Math.abs(signedDistance) * 19) * reach;
        const side = signedDistance < 0 ? -1 : 1;
        targetValue += side * ridge * fold.strength * fold.polarity * 0.2;
      }
      return clamp(targetValue, -0.34, 0.34);
    }

    function updateTopology() {
      currentSignature = mesh.probes.map((index) => {
        const node = mesh.nodes[index];
        const value = Math.tanh(node.z * 8.5);
        if (value > 0.16) return 1;
        if (value < -0.16) return -1;
        return 0;
      });
      let match = 0;
      for (let index = 0; index < target.signature.length; index += 1) {
        if (currentSignature[index] === target.signature[index]) match += 1;
        else if (currentSignature[index] === 0) match += 0.38;
      }
      coherence = clamp(match / target.signature.length, 0, 1);
      topologyChecks += 1;
      if (coherence >= RESONANCE_ENTRY && folds.length > 0) {
        // A topological wave pattern is transient by nature. The meter
        // integrates repeated correct encounters, while a short hysteresis
        // prevents a single numerical zero-crossing from erasing the phrase.
        const resonanceGain = 0.65 + coherence * 0.5;
        stableMs = Math.min(REQUIRED_STABILITY_MS, stableMs + FIXED_STEP_MS * resonanceGain);
        score += coherence * 1.85;
      } else {
        stableMs = Math.max(0, stableMs - FIXED_STEP_MS * 0.18);
        score += coherence * 0.035;
      }
      const progressBucket = Math.floor((stableMs / REQUIRED_STABILITY_MS) * 4);
      if (progressBucket !== lastProgressBucket) {
        lastProgressBucket = progressBucket;
        emit("topology", {
          ...stateSummary(),
          currentSignature: currentSignature.slice(),
          targetSignature: target.signature.slice(),
        });
      }
      if (stableMs >= REQUIRED_STABILITY_MS && status === "running") {
        status = "completed";
        score += 1200 + Math.max(0, config.foldBudget - folds.length) * 180;
        stopLoop();
        render();
        emit("complete", statePayload());
      }
    }

    function updateStep() {
      elapsedMs += FIXED_STEP_MS;
      while (elapsedMs + 1e-6 >= nextAutoWaveAt) {
        const origin = TRIANGLE[autoSourceIndex % TRIANGLE.length];
        const phase = target.phases[autoSourceIndex % target.phases.length];
        addWave(origin, "membrane", Math.cos(phase) >= 0 ? 1 : -1, 0.72, Math.sin(phase));
        autoSourceIndex += 1;
        nextAutoWaveAt += latency.intervalMs;
      }
      waves.forEach((wave) => { wave.age += FIXED_STEP_SECONDS; });
      waves = waves.filter((wave) => wave.age < 2.75);

      const accelerations = new Float64Array(mesh.nodes.length);
      let energySum = 0;
      for (const node of mesh.nodes) {
        const neighborIndices = mesh.neighbors[node.index];
        let neighborAverage = 0;
        for (const index of neighborIndices) neighborAverage += mesh.nodes[index].z;
        neighborAverage /= Math.max(1, neighborIndices.length);
        const waveDrive = waveForceAt(node);
        const foldTarget = foldTargetAt(node);
        const boundaryFactor = node.row === MESH_RESOLUTION - 1 || node.column === 0 || node.column === node.row ? 0.72 : 1;
        accelerations[node.index] = (
          (neighborAverage - node.z) * material.spring
          + (foldTarget - node.z) * material.foldCoupling
          + waveDrive * material.waveGain
          - node.z * material.relaxation
        ) * boundaryFactor;
      }
      for (const node of mesh.nodes) {
        node.velocity = clamp(
          (node.velocity + accelerations[node.index] * FIXED_STEP_SECONDS) * material.damping,
          -4,
          4,
        );
        node.z = clamp(node.z + node.velocity * FIXED_STEP_SECONDS, -0.48, 0.48);
        energySum += node.z * node.z + node.velocity * node.velocity * 0.012;
      }
      membraneEnergy = energySum / mesh.nodes.length;
      updateTopology();
    }

    function makeGradient(x0, y0, x1, y1, stops, fallback) {
      if (typeof context.createLinearGradient !== "function") return fallback;
      const gradient = context.createLinearGradient(x0, y0, x1, y1);
      stops.forEach(([offset, color]) => gradient.addColorStop(offset, color));
      return gradient;
    }

    function screenPoint(point, lift = 0) {
      return {
        x: view.x + point.x * view.width,
        y: view.y + point.y * view.height - lift * Math.min(view.width, view.height) * 0.28,
      };
    }

    function faceColor(face) {
      const average = face.reduce((sum, index) => sum + mesh.nodes[index].z, 0) / face.length;
      const hue = material.baseHue + average * 92;
      const lightness = clamp(material.lightness + average * 42, 19, 76);
      return `hsl(${round(hue, 1)} ${material.saturation}% ${round(lightness, 1)}%)`;
    }

    function drawMembrane() {
      const trianglePoints = TRIANGLE.map((point) => screenPoint(point));
      context.save();
      context.beginPath();
      context.moveTo(trianglePoints[0].x, trianglePoints[0].y);
      context.lineTo(trianglePoints[1].x, trianglePoints[1].y);
      context.lineTo(trianglePoints[2].x, trianglePoints[2].y);
      context.closePath();
      if (typeof context.clip === "function") context.clip();

      for (const face of mesh.faces) {
        const points = face.map((index) => screenPoint(mesh.nodes[index], mesh.nodes[index].z));
        context.beginPath();
        context.moveTo(points[0].x, points[0].y);
        context.lineTo(points[1].x, points[1].y);
        context.lineTo(points[2].x, points[2].y);
        context.closePath();
        context.fillStyle = faceColor(face);
        context.globalAlpha = 0.86;
        context.fill();
      }

      context.globalAlpha = 0.25;
      context.lineWidth = 0.75;
      context.strokeStyle = palette.ink;
      for (const [first, second] of mesh.edges) {
        const a = screenPoint(mesh.nodes[first], mesh.nodes[first].z);
        const b = screenPoint(mesh.nodes[second], mesh.nodes[second].z);
        context.beginPath();
        context.moveTo(a.x, a.y);
        context.lineTo(b.x, b.y);
        context.stroke();
      }

      context.globalAlpha = config.reduceMotion ? 0.25 : 0.42;
      waves.forEach((wave) => {
        if (wave.age <= 0) return;
        const center = screenPoint(wave);
        const radius = wave.age * latency.speed * Math.min(view.width, view.height);
        context.beginPath();
        context.arc(center.x, center.y, radius, 0, Math.PI * 2);
        context.strokeStyle = wave.polarity > 0 ? palette.accent : palette.counter;
        context.lineWidth = 1.3 + wave.amplitude;
        context.stroke();
      });
      context.restore();

      context.save();
      context.globalAlpha = 0.92;
      context.lineCap = "round";
      folds.forEach((fold) => {
        const start = screenPoint(fold.start);
        const end = screenPoint(fold.end);
        context.beginPath();
        context.moveTo(start.x, start.y);
        context.lineTo(end.x, end.y);
        context.strokeStyle = fold.polarity > 0 ? palette.accent : palette.counter;
        context.lineWidth = 1.5 + fold.strength * 4;
        if (typeof context.setLineDash === "function") context.setLineDash(fold.id === selectedFoldId ? [] : [4, 5]);
        context.stroke();
      });
      if (preview) {
        const start = screenPoint(preview.start);
        const end = screenPoint(preview.end);
        context.beginPath();
        context.moveTo(start.x, start.y);
        context.lineTo(end.x, end.y);
        context.strokeStyle = palette.ink;
        context.lineWidth = 2;
        if (typeof context.setLineDash === "function") context.setLineDash([6, 5]);
        context.stroke();
      }
      if (typeof context.setLineDash === "function") context.setLineDash([]);
      context.restore();

      context.save();
      context.globalAlpha = 0.88;
      mesh.probes.forEach((index, probeIndex) => {
        const node = mesh.nodes[index];
        const point = screenPoint(node, node.z);
        context.beginPath();
        context.arc(point.x, point.y, 2.4 + Math.abs(node.z) * 7, 0, Math.PI * 2);
        const matches = currentSignature[probeIndex] === target.signature[probeIndex];
        context.fillStyle = matches ? palette.ink : "rgba(5, 8, 14, 0.72)";
        context.fill();
      });
      context.restore();
    }

    function renderHud() {
      if (config.externalHud || typeof context.fillText !== "function") return;
      const margin = Math.max(14, cssWidth * 0.045);
      context.save();
      context.fillStyle = palette.ink;
      context.textAlign = "left";
      context.font = `600 ${Math.max(10, Math.min(13, cssWidth * 0.034))}px ui-monospace, monospace`;
      context.fillText(`PIEGA / ${target.label}`, margin, margin + 4);
      context.fillStyle = "rgba(230, 244, 244, 0.66)";
      context.font = `500 ${Math.max(9, Math.min(11, cssWidth * 0.029))}px ui-monospace, monospace`;
      context.fillText(`${folds.length}/${config.foldBudget} PIEGHE`, margin, margin + 22);
      context.textAlign = "right";
      context.fillStyle = palette.ink;
      context.fillText(`${Math.round(coherence * 100)}%`, cssWidth - margin, margin + 4);
      const barWidth = Math.min(112, cssWidth * 0.31);
      const barX = cssWidth - margin - barWidth;
      const barY = margin + 13;
      context.fillStyle = "rgba(255,255,255,0.12)";
      context.fillRect(barX, barY, barWidth, 4);
      context.fillStyle = palette.accent;
      context.fillRect(barX, barY, barWidth * clamp(stableMs / REQUIRED_STABILITY_MS, 0, 1), 4);
      if (status === "completed") {
        context.textAlign = "center";
        context.font = `700 ${Math.max(17, Math.min(28, cssWidth * 0.068))}px ui-monospace, monospace`;
        context.fillStyle = palette.ink;
        context.fillText("FORMA STABILIZZATA", cssWidth / 2, cssHeight * 0.52);
      }
      context.restore();
    }

    function render() {
      if (config.headless || status === "destroyed") return;
      context.setTransform?.(dpr, 0, 0, dpr, 0, 0);
      context.globalAlpha = 1;
      context.fillStyle = makeGradient(
        0,
        0,
        cssWidth,
        cssHeight,
        [[0, palette.background], [1, "#020508"]],
        palette.background,
      );
      context.fillRect(0, 0, cssWidth, cssHeight);
      drawMembrane();
      renderHud();
    }

    function stopLoop() {
      if (rafId) cancelFrame(rafId);
      rafId = 0;
      lastFrameTime = 0;
      accumulator = 0;
    }

    function scheduleLoop() {
      if (status !== "running" || rafId) return;
      rafId = requestFrame(frame);
    }

    function frame(timestamp) {
      rafId = 0;
      if (status !== "running") return;
      const time = Number(timestamp) || 0;
      if (!lastFrameTime) lastFrameTime = time - FIXED_STEP_MS;
      const delta = clamp(time - lastFrameTime, 0, FIXED_STEP_MS * MAX_FRAME_STEPS);
      lastFrameTime = time;
      accumulator += delta;
      let steps = 0;
      while (accumulator + 1e-8 >= FIXED_STEP_MS && steps < MAX_FRAME_STEPS && status === "running") {
        updateStep();
        accumulator -= FIXED_STEP_MS;
        steps += 1;
      }
      render();
      scheduleLoop();
    }

    function start() {
      if (status === "destroyed") return false;
      if (status === "running") return true;
      if (status === "completed") resetSimulation();
      status = "running";
      lastFrameTime = 0;
      accumulator = 0;
      render();
      emit("start", stateSummary());
      scheduleLoop();
      return true;
    }

    function pause() {
      if (status !== "running") return false;
      status = "paused";
      stopLoop();
      render();
      emit("pause", stateSummary());
      return true;
    }

    function resume() {
      if (status !== "paused") return false;
      status = "running";
      lastFrameTime = 0;
      accumulator = 0;
      emit("resume", stateSummary());
      scheduleLoop();
      return true;
    }

    function restart() {
      if (status === "destroyed") return false;
      stopLoop();
      resetSimulation();
      status = "running";
      render();
      emit("restart", stateSummary());
      scheduleLoop();
      return true;
    }

    function destroy() {
      if (status === "destroyed") return false;
      stopLoop();
      if (hasPointerEvents && typeof canvas.removeEventListener === "function") {
        canvas.removeEventListener("pointerdown", onCanvasPointerDown);
        canvas.removeEventListener("pointermove", onCanvasPointerMove);
        canvas.removeEventListener("pointerup", onCanvasPointerUp);
        canvas.removeEventListener("pointercancel", onCanvasPointerCancel);
      }
      pointers.clear();
      preview = null;
      multiGesture = null;
      waves = [];
      status = "destroyed";
      emit("destroy", stateSummary());
      return true;
    }

    function resize(width, height, pixelRatio) {
      if (status === "destroyed") return false;
      let nextWidth = width;
      let nextHeight = height;
      let nextDpr = pixelRatio;
      if (width && typeof width === "object") {
        nextWidth = width.width;
        nextHeight = width.height;
        nextDpr = width.dpr ?? width.pixelRatio;
      }
      const rect = typeof canvas.getBoundingClientRect === "function" ? canvas.getBoundingClientRect() : null;
      cssWidth = Math.max(1, Math.round(Number(nextWidth) || rect?.width || canvas.clientWidth || canvas.width || 390));
      cssHeight = Math.max(1, Math.round(Number(nextHeight) || rect?.height || canvas.clientHeight || canvas.height || 640));
      const explicitDpr = Number.isFinite(Number(nextDpr)) && Number(nextDpr) > 0;
      dpr = clamp(Number(nextDpr) || Number(global.devicePixelRatio) || 1, 1, explicitDpr ? 2.5 : 2);
      canvas.width = Math.max(1, Math.round(cssWidth * dpr));
      canvas.height = Math.max(1, Math.round(cssHeight * dpr));
      const side = Math.min(cssWidth, cssHeight * 0.96);
      view = {
        x: (cssWidth - side) / 2,
        y: Math.max(18, (cssHeight - side) / 2 + cssHeight * 0.035),
        width: side,
        height: side,
      };
      render();
      emit("resize", { ...stateSummary(), width: cssWidth, height: cssHeight, dpr });
      return true;
    }

    resize();

    const api = {
      start,
      pause,
      resume,
      restart,
      destroy,
      resize,
      input,
      getState,
      snapshot,
    };

    if (config.debug) {
      api.debug = Object.freeze({
        step(count = 1) {
          if (status !== "running") return false;
          const steps = clamp(Math.round(Number(count) || 1), 1, 50000);
          for (let index = 0; index < steps && status === "running"; index += 1) updateStep();
          render();
          return true;
        },
        addWave,
        setNodes(values) {
          if (status !== "running") return false;
          if (!Array.isArray(values) || values.length !== mesh.nodes.length) return false;
          mesh.nodes.forEach((node, index) => {
            node.z = clamp(Number(values[index]) || 0, -0.48, 0.48);
            node.velocity = 0;
          });
          updateTopology();
          return true;
        },
      });
    }

    return Object.freeze(api);
  }

  const namespace = global.FAIPlaylab = global.FAIPlaylab || {};
  namespace.createFold = createFold;
})(typeof globalThis !== "undefined" ? globalThis : window);
